import Pluralize from 'pluralize'
import {REPO_SELECTION, type RepoSelection} from './RepositorySelectionGroup'
import type {Cost} from '../../types'
import {ALL_REPOS_REPO_COUNT} from '../../constants'

export function getCostDisplayValues(
  repoSelection: RepoSelection,
  cost: Cost,
  selectedLicenseCount: number,
  selectedReposCount: number,
) {
  const isSelectedRepos = repoSelection === REPO_SELECTION.SELECTED
  const {per_license: perLicenseCost, increased_license_usage: increasedLicenseUsage} = cost

  const licenseCount = isSelectedRepos ? selectedLicenseCount : increasedLicenseUsage
  const repositoryCount = isSelectedRepos ? selectedReposCount : ALL_REPOS_REPO_COUNT
  const repositoryCountText = isSelectedRepos ? Pluralize('repository', repositoryCount, true) : 'all repositories'

  return {
    licenseCount,
    repositoryCount,
    repositoryCountText,
    perLicenseCost,
  }
}
