import {startTransition, useMemo, useState} from 'react'
import {Button, IconButton, Dialog} from '@primer/react'
import {ArrowLeftIcon} from '@primer/octicons-react'
import {useQuery} from '@github-ui/react-query'
import {debounce} from '@github/mini-throttle'

import type {FilterQuery, SubmitEvent} from '@github-ui/filter'

import {type RepoSelection, REPO_SELECTION} from './EstimateCostDialog/RepositorySelectionGroup'
import {RepositorySelection} from './EstimateCostDialog/RepositorySelection'
import {CostEstimation} from './EstimateCostDialog/CostEstimation'
import {queries, useEnableGhspMutation, useEnableGhspOnSelectedReposMutation} from '../api'
import {ALL_REPOS_REPO_COUNT} from '../constants'
import type {Cost, CostEstimationRepository, EnablementSuccess, Org} from '../types'
import styles from './EstimateCostDialog.module.css'
import Pluralize from 'pluralize'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {Review} from './Review'

type DialogStep = 'cost-estimation' | 'repository-selection' | 'review'

interface EstimateCostDialogProps {
  isOpen: boolean
  onClose: () => void
  cost: Cost
  org: Org
  // Handler invoked when enablement succeeds. Accepts the payload to show the banner.
  handleEnablement: (payload: EnablementSuccess) => void
  assessmentNumber: number
  assessmentDate?: string
  isEnterpriseOrMT?: boolean
}

export function EstimateCostDialog({
  isOpen,
  onClose,
  cost,
  org,
  handleEnablement,
  assessmentNumber,
  assessmentDate,
  isEnterpriseOrMT = false,
}: EstimateCostDialogProps) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const [repoSelection, setRepoSelection] = useState<RepoSelection>(REPO_SELECTION.ALL)
  const [currentStep, setCurrentStep] = useState<DialogStep>('cost-estimation')
  const [selectedRepoIds, setSelectedRepoIds] = useState<Set<number>>(() => new Set())
  const [filterValue, setFilterValue] = useState('')
  const [debouncedFilterValue, setDebouncedFilterValue] = useState('')
  const [isTransitioning, setIsTransitioning] = useState(false)

  // Debounce the filter value updates to avoid excessive API calls
  const debouncedSetFilter = debounce((value: string) => setDebouncedFilterValue(value.trim()), 300)

  // Query for repositories with server-side filtering
  const {
    data: reposData,
    isLoading,
    isError,
  } = useQuery({
    ...queries.fetchRepos(org.login, assessmentNumber, debouncedFilterValue),
    enabled: isOpen,
  })

  const reposById = useMemo(() => {
    const memo = new Map<number, CostEstimationRepository>()
    if (!reposData) return memo
    for (const repo of reposData.repositories) memo.set(repo.id, repo)
    return memo
  }, [reposData])
  const totalRepoCount = reposData?.totalCount || 0

  const handleCloseDialog = () => {
    setCurrentStep('cost-estimation')
    setRepoSelection(REPO_SELECTION.ALL)
    setSelectedRepoIds(new Set())
    setFilterValue('')
    setDebouncedFilterValue('')
    setIsTransitioning(false)
    onClose()

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: 'sp-estimate-cost-dialog',
      action: 'close',
    })
  }

  // Initialize mutations to enable Secret Protection. Use the same close handler
  // onSettled so the dialog resets and closes after the API call completes.
  const enableGhspMutation = useEnableGhspMutation({org: org.login, onSettled: handleCloseDialog})
  const enableGhspOnSelectedReposMutation = useEnableGhspOnSelectedReposMutation({
    org: org.login,
    assessmentNumber,
    onSettled: handleCloseDialog,
  })

  const handleFilterSubmit = (query: FilterQuery, _eventType: SubmitEvent) => {
    const queryValue = query.raw
    setFilterValue(queryValue)
    setDebouncedFilterValue(queryValue.trim()) // Immediate search on submit

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: 'sp-estimate-cost-dialog',
      action: 'filter-repos',
    })
  }

  const handleFilterChange = (value: string) => {
    setFilterValue(value)
    debouncedSetFilter(value)
  }

  const selectedCommitterIds = useMemo(() => {
    const memo = new Set<number>()
    for (const repoId of selectedRepoIds) {
      const repo = reposById.get(repoId)
      const committerIds = repo?.additionalCommitterIds || []
      for (const committerId of committerIds) memo.add(committerId)
    }
    return memo
  }, [reposById, selectedRepoIds])

  const onChangeSelectedRepos = (selectedRepos: CostEstimationRepository[]) => {
    setSelectedRepoIds(prev => {
      const next = new Set(prev)
      for (const repoId of reposById.keys()) next.delete(repoId)
      for (const selectedRepo of selectedRepos) next.add(selectedRepo.id)
      return next
    })
  }

  const handleBackClick = () => {
    if (currentStep === 'review') {
      setCurrentStep(repoSelection === REPO_SELECTION.SELECTED ? 'repository-selection' : 'cost-estimation')
    } else if (currentStep === 'repository-selection') {
      setCurrentStep('cost-estimation')
    }
  }

  const handleSelectRepositoriesClick = () => {
    setIsTransitioning(true)
    setCurrentStep('repository-selection')
    startTransition(() => {
      setIsTransitioning(false)
    })
  }

  const handleReviewAndEnableClick = () => {
    setCurrentStep('review')
  }

  const handleEnableSecretProtectionClick = () => {
    //  If the user chose to enable for all repositories, call the enable-all mutation and
    // set the success banner on success.
    if (repoSelection === REPO_SELECTION.ALL) {
      enableGhspMutation.mutate(
        {includePrivateRepos: true},
        {
          onSuccess: data => {
            handleEnablement({
              showBanner: true,
              repoCount: ALL_REPOS_REPO_COUNT,
              showSecurityDashboardButton: data.show_security_dashboard_button,
            })
          },
        },
      )
      sendClickAnalyticsEvent({
        location: 'security-assessment-post-scan',
        category: 'sp-estimate-cost-dialog',
        action: 'enable-all-repos',
      })
      return
    }

    // Otherwise enable for the selected repositories. Guard against no selection.
    if (selectedRepoIds.size === 0) {
      return
    }

    const repoIds = Array.from(selectedRepoIds)
    enableGhspOnSelectedReposMutation.mutate(
      {repoIds},
      {
        onSuccess: data => {
          const repoCount = typeof data.repo_count === 'number' ? data.repo_count : repoIds.length
          handleEnablement({
            showBanner: true,
            repoCount,
            showSecurityDashboardButton: data.show_security_dashboard_button,
          })
        },
      },
    )

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: 'sp-estimate-cost-dialog',
      action: 'enable-selected-repos',
      enabledRepoCount: `${selectedRepoIds.size}`,
    })
  }

  const isMutating = enableGhspMutation.isPending || enableGhspOnSelectedReposMutation.isPending

  const calculateCost = () => {
    const perLicenseAmount = parseFloat(cost?.per_license?.replace(/[$,]/g, '')) // Turns cost.per_license from something like "$9,999.99" to 9999.99
    const calculatedTotalCost = selectedCommitterIds.size * perLicenseAmount

    return {
      totalCost: calculatedTotalCost.toLocaleString('en-US', {style: 'currency', currency: 'USD'}),
      licenseCount: selectedCommitterIds.size,
    }
  }

  const renderFooter = () => {
    if (currentStep === 'repository-selection') {
      const {totalCost, licenseCount} = calculateCost()

      return (
        <div className="d-flex flex-justify-between flex-items-center p-3 border-top">
          <div>
            <div data-testid="total-cost" className="text-semibold">
              Total cost: {totalCost} / month
            </div>
            <div data-testid="license-count" className="color-fg-muted text-small">
              {licenseCount} Secret Protection {Pluralize('license', licenseCount, false)} required
            </div>
          </div>
          <div className="d-flex flex-justify-end gap-2">
            <Button onClick={handleCloseDialog}>Close</Button>
            <Button
              variant="primary"
              onClick={handleReviewAndEnableClick}
              loading={isMutating}
              disabled={repoSelection === REPO_SELECTION.SELECTED && selectedRepoIds.size === 0}
              count={selectedRepoIds.size || undefined}
            >
              Review and enable
            </Button>
          </div>
        </div>
      )
    }

    if (currentStep === 'review') {
      return (
        <div className="d-flex flex-justify-end gap-2 p-3 border-top">
          <Button onClick={handleCloseDialog}>Close</Button>
          <Button variant="primary" onClick={handleEnableSecretProtectionClick} loading={isMutating}>
            Enable Secret Protection
          </Button>
        </div>
      )
    }

    return (
      <div className="d-flex flex-justify-end gap-2 p-3 border-top">
        <Button onClick={handleCloseDialog}>Close</Button>
        {repoSelection === REPO_SELECTION.SELECTED ? (
          <Button variant="primary" onClick={handleSelectRepositoriesClick}>
            Select repositories
          </Button>
        ) : (
          <Button variant="primary" onClick={handleReviewAndEnableClick} loading={isMutating}>
            Review and enable
          </Button>
        )}
      </div>
    )
  }

  const getDialogTitle = () => {
    switch (currentStep) {
      case 'repository-selection':
        return (
          <div className="d-flex flex-items-center">
            <IconButton
              aria-label="Back to cost estimation"
              icon={ArrowLeftIcon}
              variant="invisible"
              size="small"
              onClick={handleBackClick}
              className="mr-1"
            />
            Select repositories
          </div>
        )
      case 'review':
        return (
          <div className="d-flex flex-items-center">
            <IconButton
              aria-label="Back to previous step"
              icon={ArrowLeftIcon}
              variant="invisible"
              size="small"
              onClick={handleBackClick}
              className="mr-1"
            />
            Enable Secret Protection
          </div>
        )
      case 'cost-estimation':
      default:
        return 'Estimate cost of Secret Protection'
    }
  }

  const renderDialogContent = () => {
    switch (currentStep) {
      case 'repository-selection':
        return (
          <RepositorySelection
            selectedRepoIds={selectedRepoIds}
            onRepositorySelectionChange={onChangeSelectedRepos}
            selectedCommitterIds={selectedCommitterIds}
            reposById={reposById}
            totalRepoCount={totalRepoCount}
            isLoading={isLoading || isTransitioning}
            isError={isError}
            filterValue={filterValue}
            onFilterChange={handleFilterChange}
            onFilterSubmit={handleFilterSubmit}
            orgLogin={org.login}
          />
        )
      case 'review':
        return (
          <Review
            additionalCost={repoSelection === REPO_SELECTION.ALL ? cost.total : calculateCost().totalCost}
            org={org.login}
            cost={cost}
            repoSelection={repoSelection}
            selectedReposCount={selectedRepoIds.size}
            selectedLicenseCount={
              repoSelection === REPO_SELECTION.ALL ? cost.increased_license_usage : calculateCost().licenseCount
            }
          />
        )
      case 'cost-estimation':
      default:
        return (
          <CostEstimation
            additionalCost={repoSelection === REPO_SELECTION.ALL ? cost.total : calculateCost().totalCost}
            repoSelection={repoSelection}
            selectedReposCount={selectedRepoIds.size}
            selectedLicenseCount={
              repoSelection === REPO_SELECTION.ALL ? cost.increased_license_usage : calculateCost().licenseCount
            }
            onRepoSelectionChange={setRepoSelection}
            cost={cost}
            isEnterpriseOrMT={isEnterpriseOrMT}
            org={org}
          />
        )
    }
  }

  return (
    isOpen && (
      <Dialog
        onClose={handleCloseDialog}
        height={currentStep === 'repository-selection' ? 'large' : 'auto'}
        title={getDialogTitle()}
        subtitle={
          currentStep === 'repository-selection' && (
            <div className="ml-5">
              Showing repositories without Secret Protection. Committers refers to distinct contributors with activity
              in the past 90 days. Secret count based on <span>{assessmentDate || 'latest'}</span> assessment.
            </div>
          )
        }
        renderFooter={renderFooter}
        className={currentStep === 'repository-selection' ? styles.estimateCostDialog : undefined}
      >
        {renderDialogContent()}
      </Dialog>
    )
  )
}

try{ EstimateCostDialog.displayName ||= 'EstimateCostDialog' } catch {}